(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzj-sj-prepa-sp-j7-ide3sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzj-sj-prepa-sp-j7-ide3sf3\",\n \"titre\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 57,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n   \"sha256\": \"c1e8c2d8402d3b954a7c6fc159ceb6b02b83cb88c53adce6ddd9268aa4b95034\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n     \"slug\": \"prepa-sp-j7-ide3sf3\",\n     \"pages\": \"\",\n     \"count\": 57,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Santé publique\",\n     \"source\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'approche psychosociologique des besoins en vue du diagnostic communautaire permet de déterminer les perceptions de la population relatives aux problèmes de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la démarche de diagnostic communautaire, l'approche psychosociale (ou psychosociologique) vise à recueillir les informations relatives aux perceptions, attitudes et représentations de la communauté vis-à-vis de ses propres problèmes de santé.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Diagnostic communautaire (section 5.2.3) ; Document révisé L2 2023-2024 validé, p. 43.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pastille de contrôle du vaccin (PCV) indique directement la date de péremption du vaccin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La PCV est un indicateur thermosensible qui mesure l'exposition cumulée du flacon à la chaleur grâce au changement de couleur du carré central, mais elle n'indique pas directement la date de péremption (qui figure sur l'étiquette du flacon).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des vaccins et consommables / Chaîne de froid (L2, p. 29).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La communication interpersonnelle est un processus par lequel un individu établit une relation avec une ou plusieurs personnes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La communication interpersonnelle (CIP) correspond à un échange direct (verbal et non verbal) par lequel un émetteur établit une relation interactive avec un ou plusieurs interlocuteurs afin de partager un message et susciter un changement de comportement.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. IEC / CCSC et Communication interpersonnelle, p. 98.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le goût de l'eau figure parmi les critères de choix d'une source d'approvisionnement en eau potable\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le choix d'une source d'approvisionnement en eau potable repose sur la qualité physicochimique et bactériologique (potabilité), la quantité disponible (débit suffisant), la permanence de la ressource et l'accessibilité géographique pour les populations, et non sur le goût.\\n\\nSource : Cours de Santé Publique-1, chap. Hygiène et assainissement — Approvisionnement en eau potable, p. 81 ; Cours Santé Publique L1, L2, L3 révisé 2025-2026, p. 64.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans une démarche de santé communautaire participative, les décisions concernant les actions communautaires sont prises avec la communauté\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon l'OMS, la santé communautaire est le processus par lequel les membres d'une collectivité réfléchissent ensemble sur leurs problèmes de santé, définissent leurs besoins prioritaires et participent activement à la prise de décision, à la mise en œuvre et à l'évaluation des actions.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Introduction à la santé publique, p. 7 ; Cours de Santé Publique-1, section 1.4, p. 8.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans une approche épidémiologique, l'objectif principal est uniquement la guérison individuelle du malade\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La guérison individuelle du malade est l'objectif de l'approche clinique. L'approche épidémiologique s'intéresse à la maladie en tant que phénomène de masse dans la population afin d'en assurer le contrôle, l'élimination, l'éradication ou la maîtrise.\\n\\nSource : Cours de Santé Publique-1, chap. Généralités sur l'épidémiologie (section V : Approche épidémiologique et approche clinique).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'objectif de la santé pour tous avant l'an 2000 a été défini par l'Assemblée mondiale de la Santé en 1977.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'année 1977 est marquée par la résolution de l'Assemblée mondiale de la Santé (AMS) lançant le mouvement « Santé pour tous d'ici l'an 2000 » face aux inégalités constatées dans l'offre de soins, mouvement concrétisé en 1978 par la Conférence d'Alma-Ata.\\n\\nSource : Cours de Santé Publique-1, chap. Introduction à la santé publique (section 3.4.2), p. 12.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins sont acceptables lorsque leur administration tient compte des caractéristiques socioculturelles des communautés\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon la définition d'Alma-Ata, les Soins de Santé Primaires doivent être « socialement acceptables », c'est-à-dire respectueux des valeurs, des coutumes, des croyances et des caractéristiques socioculturelles des communautés bénéficiaires.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Soins de Santé Primaires, p. 7 et p. 91 ; Cours de Santé Publique-1, section 1.5, p. 8.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision permet de déceler chez l'agent supervisé des insuffisances et d'apporter les corrections qui s'imposent\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La supervision formative est un processus d'accompagnement continu qui permet au superviseur d'identifier les insuffisances techniques ou organisationnelles de l'agent supervisé et d'y apporter immédiatement les corrections nécessaires.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision, p. 48 ; Document révisé L2 2023-2024 validé, p. 48.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour un enfant ayant abandonné la vaccination pendant une longue période, il est recommandé de reprendre son calendrier dans sa totalité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"En vaccination de routine (PEV), il existe un intervalle minimal (4 semaines) entre deux doses d'un même antigène multidose, mais aucun intervalle maximal : en cas d'interruption prolongée, on ne recommence jamais la série à zéro, on administre la dose suivante prévue au calendrier.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Programme Élargi de Vaccination (PEV), p. 28.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'approche ENGAGE-TB consiste à mobiliser un vaste ensemble d'acteurs à participer à la lutte contre la tuberculose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'approche ENGAGE-TB promue par l'OMS vise à intégrer les activités communautaires de lutte contre la tuberculose aux autres services de santé communautaire en mobilisant les ONG, les associations locales et un large éventail d'acteurs communautaires.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Programme National de Lutte contre la Tuberculose (PNLT), p. 45.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La probabilité pour une personne de développer une maladie pendant une période donnée correspond à la définition d'un déterminant de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La probabilité pour un individu indemne de développer une maladie au cours d'une période donnée correspond à la définition du risque (mesuré par l'incidence cumulée). Les déterminants de la santé sont les facteurs biologiques, comportementaux, sociaux et environnementaux qui influencent l'état de santé.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Généralités sur l'épidémiologie, p. 82.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La règle PEPU contribue à réduire les pertes de vaccins dues à leur péremption\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La règle PEPU (Premier Expiré, Premier Utilisé) impose de sortir et d'utiliser en priorité les lots de vaccins dont la date de péremption est la plus proche (ou dont la PCV a amorcé un virage), ce qui limite les pertes par péremption en stock.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des vaccins et consommables (L2, p. 29).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les effets du bruit sur la santé peuvent aboutir à des lésions organiques de l'appareil auditif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'exposition à des nuisances sonores intenses ou prolongées provoque non seulement des troubles extra-auditifs (stress, troubles du sommeil), mais également des atteintes auditives pouvant aboutir à des lésions organiques irréversibles de l'oreille interne (hypoacousie, surdité).\\n\\nSource : Cours de Santé Publique-1, chap. Hygiène et assainissement — Lutte contre les nuisances sonores, p. 81 ; Cours Santé Publique L1, L2, L3 révisé 2025-2026, p. 64.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une MAPI est une manifestation indésirable qui survient avant une vaccination et qui n'est pas nécessairement liée à l'utilisation du vaccin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Une MAPI (Manifestation Adverse Post-Immunisation) est tout incident médical fâcheux qui survient après (post-immunisation) l'administration d'un vaccin, et non avant, sans qu'il existe nécessairement un lien de causalité avéré avec le vaccin.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Programme Élargi de Vaccination (PEV), p. 28 ; Cours de Santé Publique-1, p. 2.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un système de santé efficace est toujours efficient\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'efficacité mesure le degré d'atteinte des objectifs fixés, tandis que l'efficience rapporte les résultats obtenus aux moyens financiers, humains et matériels engagés : un système peut atteindre ses objectifs (efficace) tout en gaspillant des ressources (donc sans être efficient).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Suivi et évaluation des programmes, p. 56.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins intégrés doivent être techniquement applicables et socialement acceptables, et conformes aux besoins de santé des populations et aux ressources du milieu\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon la Déclaration d'Alma-Ata (1978), ces caractéristiques (soins essentiels, scientifiquement valables, socialement acceptables, adaptés aux besoins de la communauté et à un coût supportable par le pays) définissent les Soins de Santé Primaires (SSP), et non spécifiquement les « soins intégrés ».\\n\\nSource : Cours de Santé Publique-1, chap. Introduction à la santé publique (section 1.5 : Soins de santé primaires), p. 8 ; Cours Santé Publique L1, L2, L3 révisé 2025-2026, p. 7.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Influencer le changement politique est un but du plaidoyer\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le plaidoyer est une démarche stratégique fondée sur des données probantes visant à sensibiliser et persuader les décideurs publics et leaders d'opinion afin d'obtenir un soutien institutionnel, mobiliser des ressources ou influencer un changement de politique sanitaire.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Plaidoyer, p. 104. II. ÉTUDE DE CAS N° 1 — CSR D'AKAKRO Énoncé du cas : Vous exercez au CSR d'Akakro, dans la région du Moronou. Le tableau présente les villages situés autour du centre et leurs populations au 31 décembre 2023. Le taux d'accroissement annuel est de 2 %. En 2024, les doses de Penta sorties du stock puis administrées sont : Penta 1 (1 250 ; 1 200), Penta 2 (1 170 ; 1 120) et Penta 3 (1 130 ; 1 080) ; 1 043 enfants ont été complètement vaccinés. Pour le semestre étudié, 451 enfants ont reçu au moins une dose et 430 toutes les doses requises selon le calendrier ; le score de qualité de la chaîne du froid est de 96 %. Le solde bancaire est de 1 500 000 F CFA, y compris les agios et non compris les intérêts, dont les montants sont respectivement de 50 500 F CFA et de 30 000 F CFA. La somme à budgétiser est de 800 000 F CFA, dont 150 000 F CFA de dépenses obligatoires. Une campagne de RR est prévue pour 2 700 enfants, avec un besoin théorique de 3 200 doses conditionnées en flacons de 20 doses. Le stock utilisable comprend 150 seringues d'injection et 10 seringues de dilution. Les boîtes de sécurité disponibles ont une capacité de 100 seringues chacune. Village Distance (km) Population (31/12/2023) Akakro 0 7 000 Bokro 12 3 500 N'Dakro 18 1 800 Koffikro 8 4 500 Yapokro 22 1 200 Assékro 4 5 000\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Combien de seringues d'injection faut-il commander pour la campagne de RR ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3 147 seringues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3 297 seringues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2 997 seringues\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2 847 seringues\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 2 997 seringues\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Avec une cible de 2 700 enfants (1 dose par enfant) et un facteur de perte des seringues autobloquantes (SAB) de 1,11 (taux de perte de 10 %), le besoin théorique en seringues d'injection s'élève à : 2 700 × 1,11 = 2 997 seringues. Remarque : 2 997 correspond au besoin théorique en SAB ; en ajoutant 10 % de stock de sécurité (3 297) puis en déduisant le stock utilisable de 150 seringues, la commande nette serait de 3 147 seringues.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour déterminer le solde bancaire, les agios sont déduits et les intérêts sont ajoutés au solde annoncé.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En gestion financière d'un centre de santé (COGES), le solde bancaire réel disponible s'obtient en retranchant les frais bancaires (agios) du solde annoncé et en y ajoutant les intérêts créditeurs générés par le compte.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 7 (Gestion financière du centre de santé).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la couverture vaccinale annuelle des enfants de 0 à 23 mois dans la surface de desserte? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"75,00%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"74,98%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"77,64%\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"86,92%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 74,98%\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La surface de desserte (≤ 15 km) regroupe Akakro (7 000), Assékro (5 000), Koffikro (4 500) et Bokro (3 500), soit 20 000 hab. en 2023 et 20 000 × 1,02 = 20 400 hab. en 2024. La cible des enfants de 0 à 23 mois (6,82 %) est de 20 400 × 0,0682 = 1 391 enfants, d'où une couverture vaccinale de 11 043 391 × 100 = 74,98 %.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Étude du milieu, p. 55 ; Formules de Santé Publique — Document harmonisé, chap. 1 et 5.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le taux d'abandon de Penta en 2024 ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10,00%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"11,11%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"90,00%\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"9,60%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 10,00%\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le taux d'abandon spécifique du Penta compare le nombre de doses administrées de Penta − 1 080 × 100 = 120 × 100 = 10,00 %. 1 (1 200) à celui de Penta 3 (1 080) : Taux d'abandon = 1 2001 200 1 200\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables) ; Cahier d'exercices Formules de Santé Publique, chap. 5.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Combien de boîtes de sécurité faut-il prévoir pour la campagne de RR ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"34 boîtes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"35 boîtes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"32 boîtes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"33 boîtes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 34 boîtes\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le nombre de boîtes de sécurité (capacité unitaire de 100 seringues) correspond à l'ensemble des seringues à éliminer (seringues d'injection et seringues de dilution, soit environ 3 147 + 166 313 = 33,13, arrondi par excès à 34 boîtes. = 3 313 seringues) divisé par 100, soit 3100\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Combien de seringues de dilution faut-il commander pour la campagne de RR ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"166 seringues\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"150 seringues\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"160 seringues\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"176 seringues 200 doses = 160 flacons, soit 160 seringues de dilution. En\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 166 seringues\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le besoin théorique est de 203 doses/flacon ajoutant un stock de sécurité de 10 % (16 seringues), le besoin réel est de 176 seringues ; après déduction du stock utilisable (10 seringues), il faut commander 176 − 10 = 166 seringues.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la couverture effective de la vaccination pour le semestre étudié ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"96,00%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"59,31%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"64,80%\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"61,78%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 59,31%\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La cible semestrielle des enfants de 0 à 23 mois dans la surface de desserte est de 1 391,28 ≈ 696 enfants. La couverture adéquate vaut 430 × 100 = 61,78 %. En multipliant par le score 2 696 de qualité de la chaîne du froid (96 %), la couverture effective est de 61,7816 % × 0,96 = 59,31 %.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 6 (Monitorage).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le village de N'Dakro relève de la stratégie avancée organisée par le CSR.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans l'organisation du PEV, la stratégie fixe couvre le rayon de 0 à 5 km, la stratégie avancée couvre les villages situés entre 5 et 15 km, et la stratégie mobile concerne les localités situées à plus de 15 km. N'Dakro étant à 18 km (> 15 km), il relève de la stratégie mobile (zone de silence) et non de la stratégie avancée.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. PEV (p. 28) et chap. Étude du milieu (p. 55).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont, respectivement, les effectifs annuels des enfants de 0 à 23 mois relevant des stratégies fixe et avancée en 2024 ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"835 ; 417 enfants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"973 ; 418 enfants\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1 200 ; 800 enfants\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"835 ; 557 enfants\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 835 ; 557 enfants\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"En stratégie fixe (≤ 5 km : Akakro 7 000 + Assékro 5 000 = 12 000), la population 2024 est 12 000 × 1,02 = 12 240 hab., soit 12 240 × 6,82 % = 835 enfants. En stratégie avancée (5–15 km : Koffikro 4 500 + Bokro 3 500 = 8 000), la population 2024 est 8 000 × 1,02 = 8 160 hab., soit 8 160 × 6,82 % = 557 enfants.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Étude du milieu, p. 55 ; Formules de Santé Publique — Document harmonisé, chap. 1.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nombre total de doses de Penta perdues pendant l'année est de 150 doses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les doses perdues correspondent à la différence entre les doses sorties du stock et les doses administrées : (1 250 − 1 200) + (1 170 − 1 120) + (1 130 − 1 080) = 50 + 50 + 50 = 150 doses.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont, respectivement, le solde après mouvements bancaires, le fonds de réserve et les dépenses de fonctionnement local ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 580 500 ; 780 500 ; 650 000 F CFA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1 520 500 ; 720 500 ; 650 000 F CFA\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1 479 500 ; 679 500 ; 150 000 F CFA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 479 500 ; 679 500 ; 650 000 F CFA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 1 479 500 ; 679 500 ; 650 000 F CFA\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Solde après mouvements bancaires = 1 500 000 − 50 500 + 30 000 = 1 479 500 F CFA ; fonds de réserve = 1 479 500 − 800 000 = 679 500 F CFA ; dépenses de fonctionnement local = 800 000 − 150 000 = 650 000 F CFA.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 7 (Gestion financière du centre de santé).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Comment estimer le nombre de femmes enceintes de l'aire sanitaire en 2024 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1020 femmes enceintes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1173 femmes enceintes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1204 femmes enceintes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 1173 femmes enceintes\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La population totale de l'aire sanitaire au 31/12/2023 est de 23 000 hab., soit 23 000 × 1,02 = 23 460 hab. en 2024. Le nombre de femmes enceintes (grossesses attendues) représente 5 % de la population totale : 23 460 × 5 % = 1 173 femmes enceintes.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Étude du milieu, p. 55 ; Formules de Santé Publique — Document harmonisé, chap. 1. III. QUESTIONS À CHOIX MULTIPLES ET À CHOIX UNIQUE\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les vaccins suivants, deux sont sensibles à la congélation. Lesquels ? (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"VPO\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Td\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"VPI\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"VAA\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"RR\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Td ; C. VPI\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les vaccins contenant des anatoxines ou des antigènes inactivés/adsorbés tels que le Td et le VPI sont sensibles à la congélation (perte irréversible d'efficacité), contrairement aux vaccins vivants atténués (VPO, VAA, RR) qui tolèrent la congélation.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des vaccins et consommables / Chaîne de froid (L2, p. 29).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ensemble de critères utilisés pour déterminer si une personne est atteinte d'une maladie particulière est : (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La définition de cas\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La définition de cas épidémiologique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La définition de cas pathologique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La définition de cas clinique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La définition de cas\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En surveillance épidémiologique, la définition de cas désigne l'ensemble des critères standardisés (cliniques, biologiques et épidémiologiques) utilisés pour identifier et classer de façon uniforme les personnes atteintes d'une maladie donnée.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Surveillance épidémiologique, p. 85.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quels sont les trois critères utilisés pour hiérarchiser les problèmes de santé identifiés dans une communauté ? (3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La vulnérabilité du problème\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La gravité du problème\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'ampleur du problème\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La durée des interventions.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le niveau d'instruction des populations\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"La population totale de la localité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La vulnérabilité du problème ; B. La gravité du problème ; C. L'ampleur du problème\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"La priorisation (hiérarchisation) des problèmes de santé repose sur trois critères fondamentaux : l'ampleur (fréquence, incidence, prévalence), la gravité (létalité, complications, séquelles) et la vulnérabilité (existence de moyens techniques et financiers efficaces pour agir sur le problème).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Démarche de santé publique (p. 6) et Diagnostic communautaire (L2, p. 43).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, indiquez ceux qui sont inclus dans l'investissement (3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Achat de mobylettes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Entretien des courant des locaux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Salaire du personnel journalier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Achat de réfrigérateur\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Construction d'un hangar pour la vaccination\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Achat de fournitures et administratives\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Achat de mobylettes ; D. Achat de réfrigérateur ; E. Construction d'un hangar pour la vaccination\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les dépenses d'investissement correspondent à l'acquisition de biens durables, d'équipements lourds et d'infrastructures (moyens roulants comme les mobylettes, équipements de chaîne du froid comme le réfrigérateur, construction d'un hangar), alors que les salaires, l'entretien courant et les fournitures relèvent du fonctionnement.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Identifiez parmi ces maladies hydriques celles qui sont bactériennes : (3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Poliomyélite\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dysenterie bacillaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dysenterie amibienne\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fièvre typhoïde\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Choléra\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Dysenterie bacillaire ; D. Fièvre typhoïde ; E. Choléra\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Parmi les maladies d'origine hydrique, la dysenterie bacillaire (Shigella), la fièvre typhoïde (Salmonella typhi) et le choléra (Vibrio cholerae) sont d'origine bactérienne, alors que la poliomyélite est virale et la dysenterie amibienne est parasitaire.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Hygiène et assainissement, p. 64 ; Cours de Santé Publique-1, p. 81.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles sont les deux phases du processus d'évacuation des ordures ménagères ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'élimination\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'incinération\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le stockage\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le compostage\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le traitement\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Le ramassage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Le stockage ; F. Le ramassage\",\n       \"answerLetters\": [\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Le processus d'évacuation des ordures ménagères débute par deux phases essentielles de collecte : le stockage (conservation hygiénique des déchets dans des récipients fermés au niveau des ménages) et le ramassage (enlèvement et transport vers le site de traitement ou d'élimination).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Hygiène et assainissement, p. 64 ; Cours de Santé Publique-1, p. 81.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le monitorage des services, que traduit un goulot d'étranglement entre l'accessibilité géographique et l'utilisation ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La population a accès au service, mais ne le fréquente pas\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La population accède difficilement au service, mais le fréquente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La population ne fréquente pas le service parcequ'elle n'y accède pas\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La population a accès au service, mais ne le fréquente pas\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur le graphique de monitorage (courbe de Tanahashi), un écart important entre l'accessibilité géographique et l'utilisation signifie que le service est physiquement proche et accessible, mais que la population ne le fréquente pas (problème d'accueil, d'information, de coût ou d'acceptabilité culturelle).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Suivi et évaluation / Monitorage, p. 56 ; Formules de Santé Publique — Document harmonisé, chap. 6.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but de l'Initiative de Bamako est: (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Séparer les activités de prestation et de gestion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Renforcer la mise en œuvre des soins de santé primaires\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réduire la morbidité et la mortalité maternelles et infantiles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Assurer une bonne coordination des activités\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Renforcer la mise en œuvre des soins de santé primaires\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Adoptée en 1987 à Bamako face aux difficultés rencontrées après Alma-Ata, l'Initiative de Bamako a pour but de relancer et de renforcer la mise en œuvre des Soins de Santé Primaires (SSP) par la participation communautaire à la gestion (COGES) et le recouvrement des coûts des médicaments essentiels.\\n\\nSource : Cours de Santé Publique-1, chap. Introduction à la santé publique (section 3.4.3), p. 12 ; Cours Santé Publique L1, L2, L3 révisé 2025-2026, p. 91.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Identifier la deuxième composante du suivi et évaluation: (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Intrants\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Processus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Extrants\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Impact\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Processus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le cadre logique du suivi et de l'évaluation d'un programme de santé, les composantes s'enchaînent dans l'ordre suivant : 1. Intrants (ressources), 2. Processus (activités mises en œuvre), 3. Extrants (produits immédiats), 4. Effets et 5. Impact.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Suivi et évaluation de programme et projet de santé, p. 56.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments suivants, indiquez les facteurs externes pouvant influencer le changement social de comportement: (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les attitudes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La culture\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La perception\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Les connaissances\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le milieu social\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La culture ; E. Le milieu social\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"En communication pour le changement social et de comportement (CCSC), on distingue les déterminants internes propres à l'individu (connaissances, attitudes, perceptions) des facteurs externes liés à son environnement communautaire, notamment la culture et le milieu social.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. IEC / CCSC, p. 98.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, indiquez celle qui correspond à l'objectif principal de la CMU (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"assurer un accès équitable aux soins de santé pour tous les ivoiriens\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"obliger tous les ivoiriens à participer au financement des activités de soins\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Eviter aux pauvres de bénéficier gratuitement des soins de santé des services publics\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. assurer un accès équitable aux soins de santé pour tous les ivoiriens\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La Couverture Maladie Universelle (CMU) instaurée en Côte d'Ivoire a pour objectif principal de garantir à l'ensemble de la population un accès équitable à des soins de santé de qualité en réduisant la barrière financière au moment du recours aux soins.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Système national de santé et politique nationale de santé, p. 15 ; Cours de Santé Publique-1, section 8.2.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon les règles de sécurité, quelles mesures favorisent la protection des riverains autour d'une décharge commune ? (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Entourer la décharge d'une clôture\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Éloigner la décharge des habitations\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Installer la décharge dans une zone inondable\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déverser les déchets dans un cours d'eau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Entourer la décharge d'une clôture ; B. Éloigner la décharge des habitations\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Pour prévenir les nuisances, la prolifération des vecteurs et la contamination des eaux et des populations riveraines, une décharge commune doit être éloignée des habitations (et de tout cours d'eau ou zone inondable) et entourée d'une clôture interdisant l'accès libre.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Hygiène et assainissement, p. 64 ; Cours de Santé Publique-1, p. 81.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les attitudes à développer par le personnel de santé pour mener une bonne étude du milieu sont : (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"l'observation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"la méfiance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"l'ethnocentrisme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"le dialogue\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. l'observation ; D. le dialogue\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Pour réussir l'étude du milieu et s'intégrer harmonieusement dans la communauté, l'agent de santé doit privilégier l'observation attentive des réalités locales et le dialogue ouvert avec la population, tout en évitant l'ethnocentrisme et la méfiance.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Étude du milieu, p. 55 ; Cours de Santé Publique-1, p. 29.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les maladies suivantes, indiquez celles dont la prévention se fait avec le Penta. (4 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La rubéole\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La fièvre jaune\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La méningite à Haemophilus influenzae de type B ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La coqueluche\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'hépatite B\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Le tétanos\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. La méningite à Haemophilus influenzae de type B ; ; D. La coqueluche ; E. L'hépatite B ; F. Le tétanos\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Le vaccin pentavalent (DTC-HepB-Hib) protège contre cinq pathologies : la diphtérie, le tétanos, la coqueluche, l'hépatite B et les infections invasives (dont la méningite) à Haemophilus influenzae de type b (la rubéole et la fièvre jaune étant respectivement prévenues par le RR et le VAA).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Programme Élargi de Vaccination (PEV), p. 28 ; Cours de Santé Publique-1, p. 2.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après l'analyse de la situation sanitaire, quelle est l'étape suivante de la démarche de santé publique ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Définir des priorités\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Formuler du problème avec la détermination de la population cible ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Identifier des ressources\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Définir des priorités\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La démarche de santé publique suit un ordre chronologique précis : 1. Analyse de la situation et identification des problèmes de santé ; 2. Définition des priorités ; 3. Formulation du problème et détermination de la population cible ; 4. Formulation des objectifs, etc.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Introduction à la santé publique (section VII : Étapes de la démarche de santé publique), p. 6.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le traitement DOTS vise à : (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réduire la mortalité de la tuberculose de 95% entre 2015 et 2035\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Traiter le plus grand nombre de tuberculeux à moindre coût\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réduire l'incidence de 90% entre 2015 et 2035\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Réduire l'incidence de 95% entre 2015 et 2035\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Réduire la mortalité de la tuberculose de 90% entre 2015 et 2035\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Éviter le développement des bactéries multirésistantes dû à des traitements anarchiques\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Traiter le plus grand nombre de tuberculeux à moindre coût ; F. Éviter le développement des bactéries multirésistantes dû à des traitements anarchiques\",\n       \"answerLetters\": [\n        \"B\",\n        \"F\"\n       ],\n       \"explanation\": \"La stratégie DOTS (Directly Observed Treatment, Short-course — traitement de brève durée sous surveillance directe) vise à traiter efficacement le plus grand nombre de malades à moindre coût et à garantir l'observance thérapeutique afin d'éviter l'apparition de bacilles multirésistants liée aux traitements anarchiques.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Programme National de Lutte contre la Tuberculose (PNLT), p. 45.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En Côte d'Ivoire, le gouvernement a adopté la stratégie des soins de santé primaires en: (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1994\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1993\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1991\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1981\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 1991\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, le gouvernement a officiellement adopté et lancé la stratégie des Soins de Santé Primaires (SSP) en 1991, avant sa mise en œuvre opérationnelle pilote à Bouaflé en 1993.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Soins de Santé Primaires (SSP), p. 91.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le processus de classification épidémiologique, quel est l'ordre allant du niveau initial de suspicion à la confirmation ? 1. Cas confirmé ; 2. Cas probable ; 3. Cas suspect. (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"2, 3, 1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1, 2, 3\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3, 2, 1\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"\",\n       \"answerLetters\": [],\n       \"explanation\": \"Dans la surveillance épidémiologique, la classification progressive d'un patient part du niveau initial de suspicion clinique (3. Cas suspect), passe par l'existence d'un lien épidémiologique fort (2. Cas probable) et aboutit à la validation biologique au laboratoire (1. Cas confirmé), soit l'ordre 3, 2, 1 (option C). Remarque : Cette question portait la mention « Sera évalué(e) » sans coche verte dans le sujet.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Surveillance épidémiologique, p. 85.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le domaine d'intervention de la santé qui permet aux individus de maîtriser les déterminants est: (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La protection de la santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La prévention de la santé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La promotion de la santé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La restauration de la santé\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La promotion de la santé\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon l'OMS (Charte d'Ottawa, 1986), la promotion de la santé est le processus qui confère aux individus et aux collectivités les moyens d'exercer un meilleur contrôle (maîtrise) sur les déterminants de leur santé afin de l'améliorer.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Introduction à la santé publique, p. 6 ; Cours de Santé Publique-1, section 1.11, p. 9.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, identifiez les deux attitudes de l'émetteur qui constituent des obstacles à la communication. (2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le non-respect de l'interlocuteur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La disponibilité à écouter\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'utilisation d'un langage clair\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La vérification de la compréhension du message\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une attitude méprisante\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le non-respect de l'interlocuteur ; E. Une attitude méprisante\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"En communication interpersonnelle, le non-respect de l'interlocuteur et une attitude méprisante (ou jugeante) provoquent un blocage psychologique et rompent la relation de confiance, alors que l'écoute active, la clarté du langage et la rétroaction facilitent la communication.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. IEC / CCSC et Communication interpersonnelle, p. 98.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mobilisation sociale permet de participer à: (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La réalisation des soins curatifs et préventifs\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La réalisation d'un objectif de développement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'aménagement des villes et des communautés\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La réalisation d'un objectif de développement\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La mobilisation sociale est un processus d'alliance et de participation active de l'ensemble des forces vives d'une société (autorités, société civile, communautés) en vue de la réalisation d'un objectif commun de développement et de progrès sanitaire.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Mobilisation sociale et communautaire (L2, p. 8).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avant le transfert d'un patient vers une structure de référence, quelles sont les quatre actions appropriées pour le prestataire d'un ESPC ? (4 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Informer le patient et ses accompagnants de la nécessité de la référence\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prévenir le service receveur en cas de référence urgente\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Consigner la date de référence dans le registre de consultation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Expliquer aux accompagnants qu'une contre-référence est déjà établie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Inscrire à l'avance l'heure de la contre-référence\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Remplir la fiche de référence en précisant le degré d'urgence\"\n        },\n        {\n         \"letter\": \"G\",\n         \"text\": \"G. Remettre une fiche de contre-référence vierge à la place de la fiche de référence\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Informer le patient et ses accompagnants de la nécessité de la référence ; B. Prévenir le service receveur en cas de référence urgente ; C. Consigner la date de référence dans le registre de consultation ; F. Remplir la fiche de référence en précisant le degré d'urgence\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Avant tout transfert vers l'échelon supérieur, le prestataire de l'ESPC doit : informer le patient et ses accompagnants, remplir la fiche de référence en indiquant le degré d'urgence, prévenir la structure receveuse en cas d'urgence et consigner la référence dans le registre (la contre-référence étant renseignée uniquement par la structure receveuse après les soins).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation de la référence / contreréférence (L3, p. 20).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon la classification des composantes essentielles des SSP, lesquelles sont classées comme préventives ? (3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Protection maternelle et infantile, y compris santé de la reproduction et planification familiale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prévention et lutte contre les endémies locales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Promotion de bonnes conditions alimentaires et nutritionnelles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Approvisionnement suffisant en eau saine et mesures d'assainissement de base\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Vaccination contre les principales maladies infectieuses\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Traitement des maladies et lésions courantes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Protection maternelle et infantile, y compris santé de la reproduction et planification familiale ; B. Prévention et lutte contre les endémies locales ; E. Vaccination contre les principales maladies infectieuses\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Parmi les 8 composantes essentielles des SSP, le volet préventif regroupe la PMI / planification familiale, la prévention et la lutte contre les endémies locales et la vaccination contre les principales maladies infectieuses (l'alimentation et l'eau/assainissement relèvent du volet promotionnel, et le traitement des maladies courantes du volet curatif).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Soins de Santé Primaires (SSP), p. 91.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la méthode de calcul, quel est l'ordre logique des étapes pour déterminer une commande de vaccins ? 1. Stock de sécurité ; 2. Besoin réel ; 3. Besoin théorique ; 4. Quantité à commander ; 5. Quantité en stock. (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(4, 5, 2, 1, 3)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(3, 1, 2, 5, 4)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(5, 3, 4, 2, 1)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(1, 2, 3, 4, 5)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. (3, 1, 2, 5, 4)\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le calcul d'une commande de vaccins suit l'ordre logique suivant : 1) calculer le besoin théorique (3) ; 2) calculer le stock de sécurité (1) ; 3) additionner les deux pour obtenir le besoin réel (2) ; 4) relever la quantité en stock disponible (5) ; 5) soustraire le stock disponible du besoin réel pour déterminer la quantité à commander (4), soit (3, 1, 2, 5, 4).\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables). IV. ÉTUDE DE CAS N° 2 — CSR DE LOLOBO Énoncé du cas : Vous êtes en service au CSR de LOLOBO dont l'aire sanitaire compte 20 000 habitants au 1er janvier 2024, avec un taux d'accroissement annuel constant de 2 %. En 2024, les données enregistrées sont : 5 000 cas de paludisme ; 60 diabétiques dont un tiers diagnostiqué avant 2024 ; 5 000 cas d'infections respiratoires aiguës ; 50 décès liés au paludisme ; 40 décès liés aux infections respiratoires aiguës ; 5 décès des suites du diabète.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le taux de létalité du paludisme dans l'aire sanitaire ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,8%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8,33%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 1%\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le taux de létalité rapporte le nombre de décès imputables à une maladie au nombre total de cas enregistrés de cette même maladie : Taux de létalité = 5 50 000 × 100 = 1 %.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 3 (Morbidité, incidence, prévalence et mortalité générale).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__55\",\n       \"num\": \"56\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est le taux d'incidence du diabète dans l'aire sanitaire en 2024 ? (1 bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,19%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"0,20%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0,10%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 0,19%\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur 60 diabétiques, un tiers (20) a été diagnostiqué avant 2024 ; les nouveaux cas en 2024 sont donc 60 − 20 = 40 cas. Avec une population moyenne de 20 000 +2 20 400 = 20 200 hab., le taux d'incidence est 2040200 × 100 = 0,198 % (arrondi par défaut à 0,19 %).\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 2 et 3.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j7-ide3sf3__56\",\n       \"num\": \"57\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelle est la population totale de l'aire sanitaire du CSR de Lolobo au 31 décembre 2024 ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"20 400\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"20 200\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20 100\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 20 400\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À partir d'une population initiale de 20 000 habitants au 1er janvier 2024 et d'un taux d'accroissement annuel de 2 %, la population au 31 décembre 2024 s'élève à : P2024 = 20 000 × (1 + 0,02) = 20 400 habitants (20 200 correspondant à la population moyenne).\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 2 (Démographie, natalité et fécondité).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Santé publique · Prépa D.E J7 (IDE3/SF3)\",\n       \"sourceFile\": \"J1_a_J10_SFM_IDE_fusionne_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
